/**
 * A decoded picture: tightly-packed 8-bit I420 (`data`) at the given cropped
 * dimensions. `data.len()` == `width*height + 2*ceil(width/2)*ceil(height/2)`.
 */
public struct DecodedFrame {
    /**
     * Planar I420 pixels (Y plane, then U, then V), tightly packed.
     */
    public var data: Data
    /**
     * Cropped frame width in pixels.
     */
    public var width: UInt32
    /**
     * Cropped frame height in pixels.
     */
    public var height: UInt32

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Planar I420 pixels (Y plane, then U, then V), tightly packed.
         */data: Data, 
        /**
         * Cropped frame width in pixels.
         */width: UInt32, 
        /**
         * Cropped frame height in pixels.
         */height: UInt32) {
        self.data = data
        self.width = width
        self.height = height
    }
}

#if compiler(>=6)
extension DecodedFrame: Sendable {}
#endif


extension DecodedFrame: Equatable, Hashable {
    public static func ==(lhs: DecodedFrame, rhs: DecodedFrame) -> Bool {
        if lhs.data != rhs.data {
            return false
        }
        if lhs.width != rhs.width {
            return false
        }
        if lhs.height != rhs.height {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(data)
        hasher.combine(width)
        hasher.combine(height)
    }
}



